import React, { useState } from 'react';
import { Link } from 'react-router-dom';

const STEPS = ['Voucher', 'Personal', 'Academic', 'Documents'];

const ApplicationForm: React.FC = () => {
  const [step, setStep] = useState(1);
  const [formData, setFormData] = useState({
    voucherCode: '', firstName: '', lastName: '', otherNames: '', dateOfBirth: '', gender: '',
    nationality: '', region: '', hometown: '', email: '', phone: '', address: '', programChoice: '',
    previousSchool: '', yearCompleted: '', guardianName: '', guardianPhone: '', guardianEmail: '',
  });
  const [files, setFiles] = useState<{ [key: string]: File | null }>({
    photo: null, birthCert: null, wassce: null, nmcPin: null, recommendation: null,
  });
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState({ type: '', text: '' });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) =>
    setFormData({ ...formData, [e.target.name]: e.target.value });

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files?.[0]) setFiles({ ...files, [e.target.name]: e.target.files[0] });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setMessage({ type: '', text: '' });
    try {
      await new Promise(resolve => setTimeout(resolve, 2000));
      const applicationId = `APP${Date.now().toString().slice(-6)}`;
      setMessage({ type: 'success', text: `Application submitted! Your ID is ${applicationId}. Check your email for confirmation.` });
      setTimeout(() => (window.location.href = '/application-status'), 3000);
    } catch {
      setMessage({ type: 'error', text: 'Submission failed. Please try again.' });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div>
      <header className="header">
        <div className="header-content">
          <div className="logo-section">
            <img src="http://wuc.edu.gh/wp-content/uploads/2025/05/WC-logo-on-white-1.jpg" alt="WUC Logo" />
            <div>
              <h1>Withrow University College</h1>
              <span className="logo-sub">Admission Portal</span>
            </div>
          </div>
          <nav>
            <ul className="nav-links">
              <li><Link to="/">Home</Link></li>
              <li><Link to="/purchase-voucher">Buy Voucher</Link></li>
              <li><Link to="/application-status">Check Status</Link></li>
            </ul>
          </nav>
        </div>
      </header>

      <div className="page-hero">
        <div className="page-hero-inner">
          <h2>Application Form</h2>
          <p>Complete all steps carefully. Fields marked * are required.</p>
        </div>
      </div>

      <div className="container-sm">
        {message.text && <div className={`alert alert-${message.type === 'success' ? 'success' : 'error'}`}>{message.text}</div>}

        {/* Step progress */}
        <div className="step-bar">
          {STEPS.map((label, i) => {
            const num = i + 1;
            const state = step > num ? 'done' : step === num ? 'active' : '';
            return (
              <div key={label} className={`step-item ${state}`}>
                <div className="step-dot">{step > num ? '✓' : num}</div>
                <div className="step-label">{label}</div>
              </div>
            );
          })}
        </div>

        <div className="card">
          <form onSubmit={handleSubmit}>
            {step === 1 && (
              <div>
                <h3 className="section-title">Voucher Verification</h3>
                <p className="section-subtitle">Enter the voucher code you received after payment.</p>
                <div className="form-group">
                  <label>Voucher Code *</label>
                  <input type="text" name="voucherCode" value={formData.voucherCode} onChange={handleChange}
                    placeholder="e.g. WUC12345678" required style={{ fontFamily: 'monospace', letterSpacing: '0.05em' }} />
                </div>
                <button type="button" onClick={() => setStep(2)} className="btn btn-primary">Continue →</button>
              </div>
            )}

            {step === 2 && (
              <div>
                <h3 className="section-title">Personal Information</h3>
                <div className="form-grid">
                  <div className="form-group"><label>First Name *</label><input type="text" name="firstName" value={formData.firstName} onChange={handleChange} required /></div>
                  <div className="form-group"><label>Last Name *</label><input type="text" name="lastName" value={formData.lastName} onChange={handleChange} required /></div>
                  <div className="form-group"><label>Other Names</label><input type="text" name="otherNames" value={formData.otherNames} onChange={handleChange} /></div>
                  <div className="form-group"><label>Date of Birth *</label><input type="date" name="dateOfBirth" value={formData.dateOfBirth} onChange={handleChange} required /></div>
                  <div className="form-group"><label>Gender *</label>
                    <select name="gender" value={formData.gender} onChange={handleChange} required>
                      <option value="">Select</option>
                      <option value="male">Male</option>
                      <option value="female">Female</option>
                    </select>
                  </div>
                  <div className="form-group"><label>Nationality *</label><input type="text" name="nationality" value={formData.nationality} onChange={handleChange} required /></div>
                  <div className="form-group"><label>Region *</label><input type="text" name="region" value={formData.region} onChange={handleChange} required /></div>
                  <div className="form-group"><label>Hometown *</label><input type="text" name="hometown" value={formData.hometown} onChange={handleChange} required /></div>
                  <div className="form-group"><label>Email *</label><input type="email" name="email" value={formData.email} onChange={handleChange} required /></div>
                  <div className="form-group"><label>Phone *</label><input type="tel" name="phone" value={formData.phone} onChange={handleChange} required /></div>
                </div>
                <div className="form-group"><label>Residential Address *</label><textarea name="address" value={formData.address} onChange={handleChange} rows={3} required /></div>
                <div style={{ display: 'flex', gap: '0.75rem' }}>
                  <button type="button" onClick={() => setStep(1)} className="btn btn-ghost">← Back</button>
                  <button type="button" onClick={() => setStep(3)} className="btn btn-primary">Continue →</button>
                </div>
              </div>
            )}

            {step === 3 && (
              <div>
                <h3 className="section-title">Academic & Guardian Information</h3>
                <div className="form-group">
                  <label>Programme Choice *</label>
                  <select name="programChoice" value={formData.programChoice} onChange={handleChange} required>
                    <option value="">Select Programme</option>
                    <option value="nursing">Nursing</option>
                    <option value="midwifery">Midwifery</option>
                    <option value="public-health">Public Health</option>
                    <option value="health-info">Health Information Management</option>
                    <option value="biomedical">Biomedical Science</option>
                  </select>
                </div>
                <div className="form-grid">
                  <div className="form-group"><label>Previous School *</label><input type="text" name="previousSchool" value={formData.previousSchool} onChange={handleChange} required /></div>
                  <div className="form-group"><label>Year Completed *</label><input type="number" name="yearCompleted" value={formData.yearCompleted} onChange={handleChange} min="2000" max="2026" required /></div>
                </div>
                <hr className="divider" />
                <h4 style={{ fontSize: '0.9rem', fontWeight: 700, color: 'var(--text-secondary)', marginBottom: '1rem', letterSpacing: '0.02em' }}>Guardian / Next of Kin</h4>
                <div className="form-grid">
                  <div className="form-group"><label>Guardian Name *</label><input type="text" name="guardianName" value={formData.guardianName} onChange={handleChange} required /></div>
                  <div className="form-group"><label>Guardian Phone *</label><input type="tel" name="guardianPhone" value={formData.guardianPhone} onChange={handleChange} required /></div>
                  <div className="form-group"><label>Guardian Email</label><input type="email" name="guardianEmail" value={formData.guardianEmail} onChange={handleChange} /></div>
                </div>
                <div style={{ display: 'flex', gap: '0.75rem' }}>
                  <button type="button" onClick={() => setStep(2)} className="btn btn-ghost">← Back</button>
                  <button type="button" onClick={() => setStep(4)} className="btn btn-primary">Continue →</button>
                </div>
              </div>
            )}

            {step === 4 && (
              <div>
                <h3 className="section-title">Document Upload</h3>
                <p className="section-subtitle">GTEC & NMC compliant. Accepted formats: PDF, JPG, PNG. Max 5MB each.</p>
                {[
                  { name: 'photo', label: 'Passport Photograph *', accept: 'image/*', required: true, hint: 'Recent, white background, max 2MB' },
                  { name: 'birthCert', label: 'Birth Certificate / National ID *', accept: '.pdf', required: true, hint: 'PDF only, max 5MB' },
                  { name: 'wassce', label: 'WASSCE / SSSCE Certificate *', accept: '.pdf', required: true, hint: 'PDF only, max 5MB' },
                  { name: 'nmcPin', label: 'NMC Pin (top-up applicants)', accept: '.pdf', required: false, hint: 'Optional — PDF only' },
                  { name: 'recommendation', label: 'Recommendation Letter', accept: '.pdf', required: false, hint: 'Optional — PDF only' },
                ].map(({ name, label, accept, required, hint }) => (
                  <div key={name} className="form-group">
                    <label>{label}</label>
                    <input type="file" name={name} onChange={handleFileChange} accept={accept} required={required} />
                    <span style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>{hint}</span>
                  </div>
                ))}
                <div style={{ display: 'flex', gap: '0.75rem', marginTop: '1rem' }}>
                  <button type="button" onClick={() => setStep(3)} className="btn btn-ghost">← Back</button>
                  <button type="submit" className="btn btn-success" disabled={loading}>
                    {loading ? 'Submitting...' : 'Submit Application'}
                  </button>
                </div>
              </div>
            )}
          </form>
        </div>
      </div>
    </div>
  );
};

export default ApplicationForm;
